const nextKabisCorrectionSequence = `-- name: NextKabisCorrectionSequence :one
SELECT (COALESCE(MAX(n.sequence), 0) + 1)::int AS next
FROM kabis_notifications n
WHERE n.organization_id = $1
  AND n.rental_id = $2
  AND n.event = 'correction'
`

type NextKabisCorrectionSequenceParams struct {
	OrganizationID int64 `json:"organization_id"`
	RentalID       int64 `json:"rental_id"`
}

func (q *Queries) NextKabisCorrectionSequence(ctx context.Context, arg NextKabisCorrectionSequenceParams) (int32, error) {
	row := q.db.QueryRow(ctx, nextKabisCorrectionSequence, arg.OrganizationID, arg.RentalID)
	var next int32
	err := row.Scan(&next)
	return next, err
}

const refreshKabisNotification = `-- name: RefreshKabisNotification :execrows
UPDATE kabis_notifications
SET plate = $1, payload_enc = $2, payload_hash = $3,
    summary = $4, missing_fields = $5, hold_reason = $6
WHERE organization_id = $7
  AND id = $8
`

type RefreshKabisNotificationParams struct {
	Plate          string   `json:"plate"`
	PayloadEnc     string   `json:"payload_enc"`
	PayloadHash    string   `json:"payload_hash"`
	Summary        []byte   `json:"summary"`
	MissingFields  []string `json:"missing_fields"`
	HoldReason     string   `json:"hold_reason"`
	OrganizationID int64    `json:"organization_id"`
	ID             int64    `json:"id"`
}

// A notification that was not sent yet takes the current data.
func (q *Queries) RefreshKabisNotification(ctx context.Context, arg RefreshKabisNotificationParams) (int64, error) {
	result, err := q.db.Exec(ctx, refreshKabisNotification,
		arg.Plate,
		arg.PayloadEnc,
		arg.PayloadHash,
		arg.Summary,
		arg.MissingFields,
		arg.HoldReason,
		arg.OrganizationID,
		arg.ID,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const resolveKabisJob = `-- name: ResolveKabisJob :execrows
UPDATE integration_jobs
SET status = $1::text, next_attempt_at = NULL, completed_at = NOW(), locked_until = NULL, last_error = ''
WHERE organization_id = $2
  AND id = $3
  AND status = ANY($4::text[])
  AND (locked_until IS NULL OR locked_until < NOW())
`

type ResolveKabisJobParams struct {
	Status         string      `json:"status"`
	OrganizationID pgtype.Int8 `json:"organization_id"`
	ID             int64       `json:"id"`
	FromStatuses   []string    `json:"from_statuses"`
}

// Staff resolution: reported_manually / reconciled from an allowed state,
// unless a worker holds the job.
func (q *Queries) ResolveKabisJob(ctx context.Context, arg ResolveKabisJobParams) (int64, error) {
	result, err := q.db.Exec(ctx, resolveKabisJob,
		arg.Status,
		arg.OrganizationID,
		arg.ID,
		arg.FromStatuses,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const routeKabisJob = `-- name: RouteKabisJob :execrows
UPDATE integration_jobs
SET status = $1::text, provider = $2, integration_account_id = $3,
    next_attempt_at = $4, last_error = $5
WHERE organization_id = $6
  AND id = $7
  AND (status IN ('blocked', 'waiting_dependency') OR (status = 'pending' AND attempts = 0))
  AND (locked_until IS NULL OR locked_until < NOW())
`

type RouteKabisJobParams struct {
	Status               string             `json:"status"`
	Provider             string             `json:"provider"`
	IntegrationAccountID pgtype.Int8        `json:"integration_account_id"`
	NextAttemptAt        pgtype.Timestamptz `json:"next_attempt_at"`
	LastError            string             `json:"last_error"`
	OrganizationID       pgtype.Int8        `json:"organization_id"`
	ID                   int64              `json:"id"`
}

// Moves a job that has sent nothing yet (blocked, waiting, or pending with
// no attempt) to its new state and route. A job a worker holds, or one
// that already made a call, is left alone (0 rows).
func (q *Queries) RouteKabisJob(ctx context.Context, arg RouteKabisJobParams) (int64, error) {
	result, err := q.db.Exec(ctx, routeKabisJob,
		arg.Status,
		arg.Provider,
		arg.IntegrationAccountID,
		arg.NextAttemptAt,
		arg.LastError,
		arg.OrganizationID,
		arg.ID,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

